Apply this change to `Lib/importlib/__init__.py`: Make importlib backwards-compatible to Python 2.2 (but this is not promised to last; just doing it to be nice).

Reply with the complete updated file in one code block and nothing else.

```python
"""Backport of importlib.import_module from 3.x."""
import sys

def _resolve_name(name, package, level):
    """Return the absolute name of the module to be imported."""
    level -= 1
    try:
        if package.count('.') < level:
            raise ValueError("attempted relative import beyond top-level "
                              "package")
    except AttributeError:
        raise ValueError("__package__ not set to a string")
    base = package.rsplit('.', level)[0]
    if name:
        return "%s.%s" % (base, name)
    else:
        return base


def import_module(name, package=None):
    """Import a module.

    The 'package' argument is required when performing a relative import. It
    specifies the package to use as the anchor point from which to resolve the
    relative import to an absolute import.

    """
    if name.startswith('.'):
        if not package:
            raise TypeError("relative imports require the 'package' argument")
        level = 0
        for character in name:
            if character != '.':
                break
            level += 1
        name = _resolve_name(name[level:], package, level)
    __import__(name)
    return sys.modules[name]
```

