def build_entity(entity):

    entity_formated = {
        'plural': entity.plural,
        'description': to_unicode(entity.doc)
        }
    if hasattr(entity, 'roles'):
        entity_formated['roles'] = \
            {
            role.key: build_role(role)
            for role in entity.roles
            }
