	pump.Model()
	if pump.Error() == nil {
		return
	}
	log.Printf("waking pump")
	const (
		// Older pumps should have RF enabled to increase the
		// frequency with which they listen for wakeups.
		numWakeups = 75
		xmitDelay  = 35 * time.Millisecond
	)
